import java.util.List;

public final class ClaimTotals {

    public record Claim(String id, String status, long amountCents) {
    }

    public record Summary(long totalCents, int approvedCount) {
    }

    public long approvedTotal(List<Claim> claims) {
        return summarize(claims).totalCents();
    }

    public Summary summarize(List<Claim> claims) {
        if (claims == null || claims.isEmpty()) {
            return new Summary(0L, 0);
        }
        long total = 0L;
        int count = 0;
        for (Claim claim : claims) {
            if (claim.status().equals("APPROVED")) {
                total += claim.amountCents();
                count += 1;
            }
        }
        return new Summary(total, count);
    }
}

